CREATE TABLE IF NOT EXISTS clinic_free_cache(clinic_id BIGINT UNSIGNED PRIMARY KEY,first_at DATETIME NULL,today TINYINT NOT NULL DEFAULT 0,tomorrow TINYINT NOT NULL DEFAULT 0,computed_at INT UNSIGNED NOT NULL DEFAULT 0,INDEX free_first(first_at),INDEX free_stale(computed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reviews(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL UNIQUE,doctor_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,recommend TINYINT NOT NULL,comment TEXT NULL,status VARCHAR(12) NOT NULL DEFAULT 'pending',moderated_by BIGINT UNSIGNED NULL,moderated_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX review_doctor(doctor_id,status),INDEX review_status(status,id),FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
